# Unified rule: 
# - Look RIGHT from max(6s column) first
# - If not enough, look LEFT from min(6s column)
# - Get N values in chosen direction, reverse them, fill 6s left-to-right

def apply_row(r, grid):
    result = [grid[r][c] for c in range(30)]
    sixes = [c for c in range(30) if grid[r][c] == 6]
    if not sixes:
        return result

    n = len(sixes)
    six_max = max(sixes)
    six_min = min(sixes)

    # Try look-right first
    right_sources = []
    for c in range(six_max + 1, 30):
        if grid[r][c] != 6:
            right_sources.append(grid[r][c])
            if len(right_sources) == n:
                break

    # If not enough, try look-left
    if len(right_sources) < n:
        right_sources = []
        for c in range(six_min - 1, -1, -1):
            if grid[r][c] != 6:
                right_sources.append(grid[r][c])
                if len(right_sources) == n:
                    break

    # Reverse and fill
    right_sources_reversed = right_sources[::-1]
    for i, pos in enumerate(sixes):
        result[pos] = right_sources_reversed[i]

    return result

