def find_bands(sixes):
    if not sixes:
        return []
    bands = []
    start = sixes[0]
    prev = sixes[0]
    for c in sixes[1:]:
        if c == prev + 1:
            prev = c
        else:
            bands.append((start, prev))
            start = c
            prev = c
    bands.append((start, prev))
    return bands

def apply_band(r, band, running_row):
    sixes = list(range(band[0], band[1] + 1))
    n = len(sixes)
    six_max = band[1]
    six_min = band[0]

    right_sources = []
    for c in range(six_max + 1, 30):
        if running_row[c] != 6:
            right_sources.append(running_row[c])
            if len(right_sources) == n:
                break

    if len(right_sources) < n:
        right_sources = []
        for c in range(six_min - 1, -1, -1):
            if running_row[c] != 6:
                right_sources.append(running_row[c])
                if len(right_sources) == n:
                    break

    right_sources_reversed = right_sources[::-1]
    for i, pos in enumerate(sixes):
        running_row[pos] = right_sources_reversed[i]

    return running_row

